// EXAMPLE CONTENT, never real members. Nine example profile photos: heads
// cropped from the club's own group drawing, recoloured (the same set as the
// approved mockups, v3/photos.json). They stand in for member photos on the
// fake adapters (lib/members/mock/) and in the preview harness
// (app/dev-preview) only. Each is a 200px JPEG as a data URI, so no file is
// served from /public and nothing here ships to a member's screen.

export type ExamplePhotoKey = "S" | "J" | "P" | "T" | "M" | "A" | "D" | "C" | "O";

// Letter -> the example first name the mockups use for that letter.
export const EXAMPLE_FIRST_NAMES: Record<ExamplePhotoKey, string> = {
  S: "Sam",
  J: "Jasmin",
  P: "Priya",
  T: "Tom",
  M: "Marcus",
  A: "Aisha",
  D: "Dan",
  C: "Chloe",
  O: "Ollie",
};

export const EXAMPLE_PHOTOS: Record<ExamplePhotoKey, string> = {
  S: "data:image/jpeg;base64,",
  J: "data:image/jpeg;base64,",
  P: "data:image/jpeg;base64,",
  T: "data:image/jpeg;base64,",
  M: "data:image/jpeg;base64,",
  A: "data:image/jpeg;base64,",
  D: "data:image/jpeg;base64,",
  C: "data:image/jpeg;base64,",
  O: "data:image/jpeg;base64,",
};

export function examplePhoto(key: ExamplePhotoKey): string {
  return EXAMPLE_PHOTOS[key];
}
